import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { api } from '../services/api';

const Itinerary = () => {
  const [selectedCountry, setSelectedCountry] = useState('DE');
  const [countries, setCountries] = useState([]);
  const [itinerary, setItinerary] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const loadCountries = async () => {
      try {
        const countriesData = await api.getCountries();
        setCountries(countriesData);
      } catch (error) {
        console.error('Error loading countries:', error);
      }
    };

    loadCountries();
  }, []);

  useEffect(() => {
    const loadItinerary = async () => {
      if (selectedCountry) {
        setLoading(true);
        try {
          const itineraryData = await api.getItinerary(selectedCountry);
          setItinerary(itineraryData);
        } catch (error) {
          console.error('Error loading itinerary:', error);
        } finally {
          setLoading(false);
        }
      }
    };

    loadItinerary();
  }, [selectedCountry]);

  const getDayIcon = (day) => {
    const icons = ['🌅', '☀️', '🌆', '🌙', '⭐', '🎯', '🚀'];
    return icons[(day - 1) % icons.length];
  };

  const getActivityType = (title) => {
    if (title.toLowerCase().includes('tour') || title.toLowerCase().includes('walk')) {
      return { type: 'جولة سياحية', color: 'bg-blue-100 text-blue-800' };
    }
    if (title.toLowerCase().includes('cruise') || title.toLowerCase().includes('cruise')) {
      return { type: 'نشاط مائي', color: 'bg-cyan-100 text-cyan-800' };
    }
    if (title.toLowerCase().includes('palace') || title.toLowerCase().includes('museum')) {
      return { type: 'معالم تاريخية', color: 'bg-purple-100 text-purple-800' };
    }
    return { type: 'نشاط عام', color: 'bg-gray-100 text-gray-800' };
  };

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center mb-8"
        >
          <h1 className="text-3xl font-bold text-gray-900 mb-4">
            الخطة السياحية
          </h1>
          <p className="text-lg text-gray-600">
            اكتشف خطط سياحية مقترحة لأفضل الوجهات
          </p>
        </motion.div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          {/* Country Selector */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.2 }}
            className="lg:col-span-1"
          >
            <div className="bg-white rounded-lg shadow-sm p-6 sticky top-8">
              <h2 className="text-xl font-semibold mb-6">اختر الوجهة</h2>
              
              <div className="space-y-3">
                {countries.map(country => (
                  <button
                    key={country.code}
                    onClick={() => setSelectedCountry(country.code)}
                    className={`w-full p-3 rounded-lg text-right transition-colors ${
                      selectedCountry === country.code
                        ? 'bg-blue-100 text-blue-800 border-2 border-blue-200'
                        : 'bg-gray-50 text-gray-700 hover:bg-gray-100'
                    }`}
                  >
                    <div className="font-medium">{country.name}</div>
                    <div className="text-sm opacity-75">
                      {itinerary.length > 0 ? `${itinerary.length} أنشطة` : 'لا توجد خطط'}
                    </div>
                  </button>
                ))}
              </div>

              {/* Quick Stats */}
              <div className="mt-6 p-4 bg-gray-50 rounded-lg">
                <h3 className="font-semibold text-gray-800 mb-2">إحصائيات سريعة</h3>
                <div className="space-y-2 text-sm text-gray-600">
                  <div className="flex justify-between">
                    <span>عدد الأيام:</span>
                    <span className="font-medium">{itinerary.length}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>عدد الأنشطة:</span>
                    <span className="font-medium">{itinerary.length}</span>
                  </div>
                </div>
              </div>
            </div>
          </motion.div>

          {/* Itinerary Content */}
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.4 }}
            className="lg:col-span-3"
          >
            {loading ? (
              <div className="bg-white rounded-lg shadow-sm p-8 text-center">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                <p className="mt-4 text-gray-600">جاري تحميل الخطة السياحية...</p>
              </div>
            ) : itinerary.length > 0 ? (
              <div className="space-y-6">
                {/* Header */}
                <div className="bg-white rounded-lg shadow-sm p-6">
                  <h2 className="text-2xl font-bold mb-2">
                    خطة سياحية لـ {countries.find(c => c.code === selectedCountry)?.name}
                  </h2>
                  <p className="text-gray-600">
                    خطط مقترحة ومصممة خصيصاً لاستكشاف أفضل ما في هذه الوجهة
                  </p>
                </div>

                {/* Timeline */}
                <div className="space-y-6">
                  {itinerary.map((item, index) => {
                    const activityType = getActivityType(item.title);
                    return (
                      <motion.div
                        key={index}
                        initial={{ opacity: 0, x: 20 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: 0.1 * index }}
                        className="bg-white rounded-lg shadow-sm p-6 hover:shadow-md transition-shadow"
                      >
                        <div className="flex items-start space-x-4 rtl:space-x-reverse">
                          {/* Day Number */}
                          <div className="flex-shrink-0">
                            <div className="w-12 h-12 bg-blue-100 rounded-full flex items-center justify-center">
                              <span className="text-lg font-bold text-blue-600">
                                {item.day}
                              </span>
                            </div>
                          </div>

                          {/* Content */}
                          <div className="flex-1">
                            <div className="flex items-start justify-between mb-3">
                              <div>
                                <h3 className="text-xl font-semibold text-gray-900 mb-1">
                                  {item.title}
                                </h3>
                                <p className="text-gray-600 text-sm">
                                  اليوم {item.day} من الرحلة
                                </p>
                              </div>
                              <div className="flex items-center space-x-2 rtl:space-x-reverse">
                                <span className="text-2xl">{getDayIcon(item.day)}</span>
                                <span className={`px-3 py-1 rounded-full text-xs font-medium ${activityType.color}`}>
                                  {activityType.type}
                                </span>
                              </div>
                            </div>

                            <div className="bg-gray-50 rounded-lg p-4">
                              <p className="text-gray-700">{item.note}</p>
                            </div>

                            {/* Additional Info */}
                            <div className="mt-4 flex items-center space-x-4 rtl:space-x-reverse text-sm text-gray-500">
                              <div className="flex items-center space-x-1 rtl:space-x-reverse">
                                <span>⏰</span>
                                <span>مدة النشاط: 4-6 ساعات</span>
                              </div>
                              <div className="flex items-center space-x-1 rtl:space-x-reverse">
                                <span>💰</span>
                                <span>التكلفة: $50-100</span>
                              </div>
                              <div className="flex items-center space-x-1 rtl:space-x-reverse">
                                <span>⭐</span>
                                <span>التقييم: 4.5/5</span>
                              </div>
                            </div>
                          </div>
                        </div>
                      </motion.div>
                    );
                  })}
                </div>

                {/* Travel Tips */}
                <div className="bg-blue-50 border border-blue-200 rounded-lg p-6">
                  <h3 className="text-lg font-semibold text-blue-800 mb-4">نصائح السفر</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <h4 className="font-medium text-blue-700 mb-2">قبل السفر</h4>
                      <ul className="text-sm text-blue-600 space-y-1">
                        <li>• تأكد من صحة جواز السفر</li>
                        <li>• احجز الفنادق مسبقاً</li>
                        <li>• اشتري تأمين السفر</li>
                        <li>• تحقق من متطلبات التأشيرة</li>
                      </ul>
                    </div>
                    <div>
                      <h4 className="font-medium text-blue-700 mb-2">أثناء السفر</h4>
                      <ul className="text-sm text-blue-600 space-y-1">
                        <li>• احمل نسخ من الوثائق المهمة</li>
                        <li>• استخدم وسائل النقل العام</li>
                        <li>• تعلم بعض الكلمات المحلية</li>
                        <li>• احتفظ بأرقام الطوارئ</li>
                      </ul>
                    </div>
                  </div>
                </div>

                {/* Map Preview */}
                <div className="bg-white rounded-lg shadow-sm p-6">
                  <h3 className="text-lg font-semibold mb-4">خريطة الرحلة</h3>
                  <div className="bg-gray-100 rounded-lg h-48 flex items-center justify-center">
                    <div className="text-center">
                      <div className="text-4xl mb-2">🗺️</div>
                      <p className="text-gray-600">خريطة تفاعلية للرحلة</p>
                      <p className="text-sm text-gray-500">يمكن دمجها مع خرائط Google أو Apple</p>
                    </div>
                  </div>
                </div>

                {/* Disclaimer */}
                <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
                  <p className="text-xs text-gray-600 text-center">
                    * هذه الخطط تجريبية/مقترحة لأغراض العرض التوضيحي. 
                    يمكن تخصيصها حسب الاهتمامات والميزانية المتاحة.
                  </p>
                </div>
              </div>
            ) : (
              <div className="bg-white rounded-lg shadow-sm p-8 text-center">
                <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                  <span className="text-2xl">🗺️</span>
                </div>
                <h3 className="text-lg font-semibold text-gray-900 mb-2">
                  لا توجد خطط متاحة
                </h3>
                <p className="text-gray-600 mb-4">
                  لا توجد خطط سياحية متاحة لهذه الوجهة حالياً.
                </p>
                <p className="text-sm text-gray-500">
                  هذه المنطقة جاهزة للدمج مع مزودات POI (Points of Interest) 
                  مثل Google Places API أو Foursquare API
                </p>
              </div>
            )}
          </motion.div>
        </div>
      </div>
    </div>
  );
};

export default Itinerary;
