import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { api } from '../services/api';

const JobsSnapshot = () => {
  const [selectedCountry, setSelectedCountry] = useState('DE');
  const [countries, setCountries] = useState([]);
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const loadCountries = async () => {
      try {
        const countriesData = await api.getCountries();
        setCountries(countriesData);
      } catch (error) {
        console.error('Error loading countries:', error);
      }
    };

    loadCountries();
  }, []);

  useEffect(() => {
    const loadJobs = async () => {
      if (selectedCountry) {
        setLoading(true);
        try {
          const jobsData = await api.getJobsByCountry(selectedCountry);
          setJobs(jobsData);
        } catch (error) {
          console.error('Error loading jobs:', error);
        } finally {
          setLoading(false);
        }
      }
    };

    loadJobs();
  }, [selectedCountry]);

  const getSalaryColor = (salary) => {
    if (salary >= 80000) return 'text-green-600 bg-green-100';
    if (salary >= 40000) return 'text-blue-600 bg-blue-100';
    if (salary >= 20000) return 'text-yellow-600 bg-yellow-100';
    return 'text-gray-600 bg-gray-100';
  };

  const getSalaryLevel = (salary) => {
    if (salary >= 80000) return 'مرتفع جداً';
    if (salary >= 40000) return 'مرتفع';
    if (salary >= 20000) return 'متوسط';
    return 'منخفض';
  };

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center mb-8"
        >
          <h1 className="text-3xl font-bold text-gray-900 mb-4">
            سوق العمل
          </h1>
          <p className="text-lg text-gray-600">
            استكشف فرص العمل والرواتب في مختلف الدول
          </p>
        </motion.div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          {/* Country Selector */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.2 }}
            className="lg:col-span-1"
          >
            <div className="bg-white rounded-lg shadow-sm p-6 sticky top-8">
              <h2 className="text-xl font-semibold mb-6">اختر الدولة</h2>
              
              <div className="space-y-3">
                {countries.map(country => (
                  <button
                    key={country.code}
                    onClick={() => setSelectedCountry(country.code)}
                    className={`w-full p-3 rounded-lg text-right transition-colors ${
                      selectedCountry === country.code
                        ? 'bg-blue-100 text-blue-800 border-2 border-blue-200'
                        : 'bg-gray-50 text-gray-700 hover:bg-gray-100'
                    }`}
                  >
                    <div className="font-medium">{country.name}</div>
                    <div className="text-sm opacity-75">{country.currency}</div>
                  </button>
                ))}
              </div>

              {/* Market Overview */}
              <div className="mt-6 p-4 bg-gray-50 rounded-lg">
                <h3 className="font-semibold text-gray-800 mb-2">نظرة عامة على السوق</h3>
                <div className="space-y-2 text-sm text-gray-600">
                  <div className="flex justify-between">
                    <span>عدد الوظائف المتاحة:</span>
                    <span className="font-medium">{jobs.length}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>متوسط الراتب:</span>
                    <span className="font-medium">
                      ${jobs.length > 0 ? Math.round(jobs.reduce((sum, job) => sum + job.avgSalary, 0) / jobs.length).toLocaleString() : 0}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </motion.div>

          {/* Jobs List */}
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.4 }}
            className="lg:col-span-3"
          >
            {loading ? (
              <div className="bg-white rounded-lg shadow-sm p-8 text-center">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                <p className="mt-4 text-gray-600">جاري تحميل بيانات سوق العمل...</p>
              </div>
            ) : jobs.length > 0 ? (
              <div className="space-y-6">
                {/* Header */}
                <div className="bg-white rounded-lg shadow-sm p-6">
                  <h2 className="text-2xl font-bold mb-2">
                    فرص العمل في {countries.find(c => c.code === selectedCountry)?.name}
                  </h2>
                  <p className="text-gray-600">
                    بيانات تجريبية/مقترحة لأغراض العرض التوضيحي
                  </p>
                </div>

                {/* Jobs Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {jobs.map((job, index) => (
                    <motion.div
                      key={index}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: 0.1 * index }}
                      className="bg-white rounded-lg shadow-sm p-6 hover:shadow-md transition-shadow"
                    >
                      <div className="flex items-start justify-between mb-4">
                        <div>
                          <h3 className="text-lg font-semibold text-gray-900 mb-1">
                            {job.title}
                          </h3>
                          <p className="text-sm text-gray-600">
                            متوسط الراتب السنوي
                          </p>
                        </div>
                        <div className={`px-3 py-1 rounded-full text-sm font-medium ${getSalaryColor(job.avgSalary)}`}>
                          {getSalaryLevel(job.avgSalary)}
                        </div>
                      </div>

                      <div className="space-y-3">
                        <div className="flex items-center justify-between">
                          <span className="text-sm text-gray-600">الراتب السنوي</span>
                          <span className="text-2xl font-bold text-gray-900">
                            ${job.avgSalary.toLocaleString()}
                          </span>
                        </div>
                        
                        <div className="flex items-center justify-between">
                          <span className="text-sm text-gray-600">الراتب الشهري</span>
                          <span className="text-lg font-semibold text-gray-700">
                            ${Math.round(job.avgSalary / 12).toLocaleString()}
                          </span>
                        </div>

                        <div className="pt-3 border-t border-gray-100">
                          <div className="flex items-center justify-between text-sm">
                            <span className="text-gray-600">مستوى الراتب</span>
                            <div className="flex items-center space-x-1 rtl:space-x-reverse">
                              {[1, 2, 3, 4, 5].map((level) => (
                                <div
                                  key={level}
                                  className={`w-3 h-3 rounded-full ${
                                    level <= (job.avgSalary >= 80000 ? 5 : job.avgSalary >= 40000 ? 4 : job.avgSalary >= 20000 ? 3 : 2)
                                      ? 'bg-blue-500'
                                      : 'bg-gray-200'
                                  }`}
                                />
                              ))}
                            </div>
                          </div>
                        </div>
                      </div>
                    </motion.div>
                  ))}
                </div>

                {/* Market Analysis */}
                <div className="bg-white rounded-lg shadow-sm p-6">
                  <h3 className="text-xl font-semibold mb-6">تحليل سوق العمل</h3>
                  
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {/* Salary Distribution */}
                    <div className="text-center">
                      <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-3">
                        <span className="text-2xl">💰</span>
                      </div>
                      <h4 className="font-semibold mb-2">توزيع الرواتب</h4>
                      <p className="text-sm text-gray-600">
                        أعلى راتب: ${Math.max(...jobs.map(j => j.avgSalary)).toLocaleString()}
                      </p>
                      <p className="text-sm text-gray-600">
                        أقل راتب: ${Math.min(...jobs.map(j => j.avgSalary)).toLocaleString()}
                      </p>
                    </div>

                    {/* Job Categories */}
                    <div className="text-center">
                      <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-3">
                        <span className="text-2xl">💼</span>
                      </div>
                      <h4 className="font-semibold mb-2">مجالات العمل</h4>
                      <p className="text-sm text-gray-600">
                        {jobs.filter(j => j.title.toLowerCase().includes('engineer')).length} وظائف هندسية
                      </p>
                      <p className="text-sm text-gray-600">
                        {jobs.filter(j => j.title.toLowerCase().includes('developer')).length} وظائف تطوير
                      </p>
                    </div>

                    {/* Market Trends */}
                    <div className="text-center">
                      <div className="w-16 h-16 bg-yellow-100 rounded-full flex items-center justify-center mx-auto mb-3">
                        <span className="text-2xl">📈</span>
                      </div>
                      <h4 className="font-semibold mb-2">اتجاهات السوق</h4>
                      <p className="text-sm text-gray-600">
                        نمو متوقع في التقنية
                      </p>
                      <p className="text-sm text-gray-600">
                        طلب عالي على المطورين
                      </p>
                    </div>
                  </div>
                </div>

                {/* Disclaimer */}
                <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
                  <p className="text-xs text-gray-600 text-center">
                    * هذه البيانات تجريبية/مقترحة لأغراض العرض التوضيحي. 
                    الرواتب الفعلية قد تختلف حسب الخبرة والموقع والشركة.
                  </p>
                </div>
              </div>
            ) : (
              <div className="bg-white rounded-lg shadow-sm p-8 text-center">
                <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                  <span className="text-2xl">📊</span>
                </div>
                <h3 className="text-lg font-semibold text-gray-900 mb-2">
                  لا توجد بيانات متاحة
                </h3>
                <p className="text-gray-600">
                  لا توجد بيانات تجريبية متاحة لهذه الدولة حالياً.
                </p>
              </div>
            )}
          </motion.div>
        </div>
      </div>
    </div>
  );
};

export default JobsSnapshot;
