// API service layer to simulate real API calls
import { mockedCountries, visaMatrix, sampleJobs, itineraries } from '../data/mocks.js';

// Simulate API delay
const delay = (ms = 500) => new Promise(resolve => setTimeout(resolve, ms));

export const api = {
  // Get all countries
  async getCountries() {
    await delay(200);
    return Promise.resolve(mockedCountries);
  },

  // Get visa status between two countries
  async getVisaStatus(from, to) {
    await delay(300);
    const status = visaMatrix[from] ? visaMatrix[from][to] || 'unknown' : 'unknown';
    return Promise.resolve({
      from,
      to,
      status,
      badge: {
        'visa-free': 'بدون فيزا',
        'e-visa': 'تأشيرة إلكترونية',
        'visa-on-arrival': 'تأشيرة عند الوصول',
        'visa-required': 'تتطلب تأشيرة مسبقة',
        unknown: 'غير متوفر'
      }[status]
    });
  },

  // Get job market data for a country
  async getJobsByCountry(countryCode) {
    await delay(400);
    const jobs = sampleJobs[countryCode] || [];
    return Promise.resolve(jobs);
  },

  // Get itinerary for a country
  async getItinerary(countryCode) {
    await delay(350);
    const itinerary = itineraries[countryCode] || [];
    return Promise.resolve(itinerary);
  },

  // Calculate trip cost
  async calculateTripCost(from, to, days = 6) {
    await delay(250);
    
    // Simple heuristic for demo
    let baseFlight = 0;
    if (from !== to) {
      if (from === 'PS' && to === 'DE') baseFlight = 450;
      else if (from === 'PS' && to === 'TR') baseFlight = 180;
      else if (from === 'PS' && to === 'QA') baseFlight = 140;
      else baseFlight = 350;
    }

    const daily = 80; // average daily expense in demo USD
    const total = baseFlight + daily * days;

    return Promise.resolve({
      baseFlight,
      daily,
      days,
      total
    });
  }
};
