import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { api } from '../services/api';

const VisaLookup = () => {
  const [from, setFrom] = useState('PS');
  const [to, setTo] = useState('DE');
  const [countries, setCountries] = useState([]);
  const [visaStatus, setVisaStatus] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const loadCountries = async () => {
      try {
        const countriesData = await api.getCountries();
        setCountries(countriesData);
      } catch (error) {
        console.error('Error loading countries:', error);
      }
    };

    loadCountries();
  }, []);

  useEffect(() => {
    const loadVisaStatus = async () => {
      if (from && to) {
        setLoading(true);
        try {
          const visaData = await api.getVisaStatus(from, to);
          setVisaStatus(visaData);
        } catch (error) {
          console.error('Error loading visa status:', error);
        } finally {
          setLoading(false);
        }
      }
    };

    loadVisaStatus();
  }, [from, to]);

  const getStatusColor = (status) => {
    switch (status) {
      case 'visa-free':
        return 'bg-green-100 text-green-800 border-green-200';
      case 'e-visa':
        return 'bg-blue-100 text-blue-800 border-blue-200';
      case 'visa-on-arrival':
        return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case 'visa-required':
        return 'bg-red-100 text-red-800 border-red-200';
      default:
        return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'visa-free':
        return '✅';
      case 'e-visa':
        return '💻';
      case 'visa-on-arrival':
        return '🏛️';
      case 'visa-required':
        return '📋';
      default:
        return '❓';
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center mb-8"
        >
          <h1 className="text-3xl font-bold text-gray-900 mb-4">
            البحث عن التأشيرة
          </h1>
          <p className="text-lg text-gray-600">
            اكتشف متطلبات التأشيرة بين الدول المختلفة
          </p>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="bg-white rounded-lg shadow-sm p-8"
        >
          {/* Country Selector */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                الدولة الحالية
              </label>
              <select
                value={from}
                onChange={(e) => setFrom(e.target.value)}
                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                disabled={loading}
              >
                {countries.map(country => (
                  <option key={country.code} value={country.code}>
                    {country.name}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                الدولة الوجهة
              </label>
              <select
                value={to}
                onChange={(e) => setTo(e.target.value)}
                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                disabled={loading}
              >
                {countries.map(country => (
                  <option key={country.code} value={country.code}>
                    {country.name}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Visa Status Result */}
          {loading ? (
            <div className="text-center py-8">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
              <p className="mt-4 text-gray-600">جاري البحث عن معلومات التأشيرة...</p>
            </div>
          ) : visaStatus ? (
            <div className="space-y-6">
              {/* Main Status Card */}
              <div className={`border-2 rounded-lg p-6 ${getStatusColor(visaStatus.status)}`}>
                <div className="flex items-center justify-between">
                  <div>
                    <h3 className="text-xl font-semibold mb-2">
                      حالة التأشيرة
                    </h3>
                    <p className="text-sm opacity-75">
                      من {countries.find(c => c.code === from)?.name} إلى {countries.find(c => c.code === to)?.name}
                    </p>
                  </div>
                  <div className="text-4xl">
                    {getStatusIcon(visaStatus.status)}
                  </div>
                </div>
                <div className="mt-4">
                  <span className="text-2xl font-bold">
                    {visaStatus.badge}
                  </span>
                  <p className="text-sm opacity-75 mt-1">
                    (بيانات تجريبية/مقترحة)
                  </p>
                </div>
              </div>

              {/* Additional Information */}
              <div className="bg-gray-50 rounded-lg p-6">
                <h4 className="text-lg font-semibold mb-4">معلومات إضافية</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <h5 className="font-medium text-gray-700 mb-2">نوع التأشيرة</h5>
                    <p className="text-sm text-gray-600">
                      {visaStatus.status === 'visa-free' && 'لا توجد متطلبات تأشيرة'}
                      {visaStatus.status === 'e-visa' && 'تأشيرة إلكترونية - يمكن التقديم عبر الإنترنت'}
                      {visaStatus.status === 'visa-on-arrival' && 'تأشيرة عند الوصول - يمكن الحصول عليها في المطار'}
                      {visaStatus.status === 'visa-required' && 'تأشيرة مطلوبة - يجب التقديم مسبقاً'}
                    </p>
                  </div>
                  <div>
                    <h5 className="font-medium text-gray-700 mb-2">ملاحظات</h5>
                    <p className="text-sm text-gray-600">
                      هذه المعلومات تقديرية وقد تتغير. يُنصح بالتحقق من السفارة أو القنصلية للدولة الوجهة للحصول على أحدث المعلومات.
                    </p>
                  </div>
                </div>
              </div>

              {/* Visa Matrix for Multiple Countries */}
              <div className="bg-white border rounded-lg p-6">
                <h4 className="text-lg font-semibold mb-4">مصفوفة التأشيرات</h4>
                <div className="overflow-x-auto">
                  <table className="min-w-full">
                    <thead>
                      <tr className="border-b">
                        <th className="text-right py-2 px-4 font-medium text-gray-700">من</th>
                        <th className="text-right py-2 px-4 font-medium text-gray-700">إلى</th>
                        <th className="text-right py-2 px-4 font-medium text-gray-700">الحالة</th>
                      </tr>
                    </thead>
                    <tbody>
                      {countries.slice(0, 5).map(country => (
                        <tr key={country.code} className="border-b">
                          <td className="py-2 px-4 text-sm">{country.name}</td>
                          <td className="py-2 px-4 text-sm">{countries.find(c => c.code === to)?.name}</td>
                          <td className="py-2 px-4 text-sm">
                            <span className={`px-2 py-1 rounded-full text-xs ${getStatusColor('visa-required')}`}>
                              {country.code === to ? 'نفس الدولة' : 'تتطلب تأشيرة'}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <p className="text-xs text-gray-500 mt-4">
                  * هذه البيانات تجريبية/مقترحة لأغراض العرض التوضيحي
                </p>
              </div>
            </div>
          ) : null}
        </motion.div>
      </div>
    </div>
  );
};

export default VisaLookup;
