import React, { useState, useEffect, useMemo } from 'react';
import { motion } from 'framer-motion';
import { api } from '../services/api';

const fadeUp = (delay = 0) => ({
  initial: { opacity: 0, y: 16 },
  animate: { opacity: 1, y: 0, transition: { duration: 0.45, delay } }
});

const StatPill = ({ icon, label }) => (
  <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/80 border text-sm">
    <span className="text-lg">{icon}</span>
    <span className="text-gray-700">{label}</span>
  </div>
);

const Skeleton = () => (
  <div className="animate-pulse space-y-3">
    <div className="h-4 bg-gray-200 rounded w-3/4" />
    <div className="h-4 bg-gray-200 rounded w-2/4" />
    <div className="h-4 bg-gray-200 rounded w-1/3" />
  </div>
);

export default function Home() {
  const [from, setFrom] = useState('PS');
  const [to, setTo] = useState('DE');
  const [countries, setCountries] = useState([]);
  const [visaStatus, setVisaStatus] = useState(null);
  const [costData, setCostData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState('');

  const canSwap = useMemo(() => from && to && from !== to, [from, to]);

  useEffect(() => {
    let mounted = true;
    const load = async () => {
      setLoading(true);
      setErr('');
      try {
        const [cs, vs, cost] = await Promise.all([
          api.getCountries(),
          api.getVisaStatus(from, to),
          api.calculateTripCost(from, to),
        ]);
        if (!mounted) return;
        setCountries(cs || []);
        setVisaStatus(vs || null);
        setCostData(cost || null);
      } catch (e) {
        if (!mounted) return;
        setErr('تعذر تحميل البيانات. حاول مجدداً.');
      } finally {
        if (mounted) setLoading(false);
      }
    };
    load();
    return () => { mounted = false; };
  }, [from, to]);

  const swapCountries = () => {
    if (!canSwap) return;
    setFrom(to);
    setTo(from);
  };

  return (
    <div dir="rtl" className="min-h-screen bg-gradient-to-b from-blue-50 via-slate-50 to-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">

        {/* HERO */}
        <motion.section {...fadeUp(0)} className="relative overflow-hidden rounded-3xl bg-gradient-to-tr from-blue-600 to-indigo-600 text-white p-8 md:p-12 mb-10">
          <div className="relative z-10">
            <div className="flex flex-wrap items-center gap-3 mb-4">
              <span className="px-3 py-1 rounded-full bg-white/15 border border-white/20 text-sm">🚧 نموذج منتج (Concept)</span>
              <span className="px-3 py-1 rounded-full bg-white/15 border border-white/20 text-sm">✨ نسخة أولية قابلة للتوسّع</span>
            </div>
            <h1 className="text-3xl md:text-5xl font-extrabold leading-tight">
              TravelInsight — اكتشف إلى أين يمكنك السفر وماذا تتوقع هناك
            </h1>
            <p className="mt-3 md:text-lg text-blue-100/90 max-w-3xl">
              اختر دولتك ووجهتك لتحصل على حالة التأشيرة، تقدير التكلفة، ولمحة سريعة عن سوق العمل — في تجربة واحدة بسيطة.
            </p>

            <div className="mt-6 flex flex-wrap items-center gap-3">
              <StatPill icon="🛂" label="حالة التأشيرة فوريًا" />
              <StatPill icon="💰" label="تقدير تكاليف سريع" />
              <StatPill icon="💼" label="سوق العمل بالوجهة" />
            </div>
          </div>
          <div className="absolute -left-24 -bottom-24 w-72 h-72 bg-white/10 rounded-full blur-2xl" />
          <div className="absolute -right-20 -top-20 w-64 h-64 bg-white/10 rounded-full blur-2xl" />
        </motion.section>

        {/* SEARCH PANEL + RESULTS */}
        <motion.section {...fadeUp(0.05)} className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Left: Search Panel */}
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white rounded-2xl shadow-sm border p-6">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-bold">ابدأ هنا — اختر دولتك ووجهتك</h2>
                <button
                  onClick={swapCountries}
                  disabled={!canSwap || loading}
                  className={`px-3 py-2 rounded-lg border text-sm ${canSwap ? 'hover:bg-gray-50' : 'opacity-50 cursor-not-allowed'}`}
                  title="تبديل الدول"
                >
                  ⇆ تبديل
                </button>
              </div>

              {err && (
                <div className="mb-4 p-3 rounded-lg bg-red-50 border border-red-200 text-red-700 text-sm">
                  {err}
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">الدولة الحالية</label>
                  <select
                    value={from}
                    onChange={(e) => setFrom(e.target.value)}
                    className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    disabled={loading}
                  >
                    {countries.map(c => (
                      <option key={c.code} value={c.code}>{c.name}</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">الوجهة</label>
                  <select
                    value={to}
                    onChange={(e) => setTo(e.target.value)}
                    className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    disabled={loading}
                  >
                    {countries.map(c => (
                      <option key={c.code} value={c.code}>{c.name}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="mt-4 text-xs text-gray-500">
                * البيانات الحالية تجريبية. عند التحويل لمنتج سيتم ربط مصادر رسمية للتأشيرات والتكاليف والوظائف.
              </div>
            </div>

            {/* Results cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Visa */}
              <div className="bg-white rounded-2xl shadow-sm border p-6">
                <h3 className="text-lg font-semibold mb-3">حالة التأشيرة</h3>
                {loading ? (
                  <Skeleton />
                ) : visaStatus ? (
                  <div className="space-y-3">
                    <div className="flex flex-wrap items-center gap-2 text-sm text-gray-600">
                      <span>من</span>
                      <strong>{countries.find(c => c.code === from)?.name}</strong>
                      <span>إلى</span>
                      <strong>{countries.find(c => c.code === to)?.name}</strong>
                    </div>
                    <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-blue-50 border border-blue-200">
                      <span className="font-medium text-blue-800">{visaStatus.badge}</span>
                      <small className="text-xs text-blue-700/80">(تقديري)</small>
                    </div>
                    {visaStatus.note && (
                      <p className="text-sm text-gray-600">{visaStatus.note}</p>
                    )}
                  </div>
                ) : (
                  <p className="text-sm text-gray-500">اختر دولتك ووجهتك لمعرفة الحالة.</p>
                )}
              </div>

              {/* Cost */}
              <div className="bg-white rounded-2xl shadow-sm border p-6">
                <h3 className="text-lg font-semibold mb-3">تقدير التكلفة</h3>
                {loading ? (
                  <Skeleton />
                ) : costData ? (
                  <div className="space-y-3">
                    <div className="flex justify-between items-center">
                      <span className="text-sm text-gray-600">تكلفة الطيران</span>
                      <span className="font-semibold">${costData.baseFlight}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-sm text-gray-600">مصاريف يومية × {costData.days}</span>
                      <span className="font-semibold">${costData.daily} × {costData.days}</span>
                    </div>
                    <div className="border-t pt-3 flex justify-between items-center">
                      <span className="font-medium">الإجمالي التقريبي</span>
                      <span className="text-lg font-bold text-blue-600">${costData.total}</span>
                    </div>
                  </div>
                ) : (
                  <p className="text-sm text-gray-500">سنقوم بحساب التكاليف عند اختيار الدول.</p>
                )}
              </div>
            </div>

            {/* Note about Acceptance */}
            <div className="rounded-2xl p-6 bg-yellow-50 border border-yellow-200">
              <h3 className="text-lg font-semibold text-yellow-800 mb-2">بخصوص «نِسَب قبول التأشيرة»</h3>
              <p className="text-yellow-800/90 text-sm leading-6">
                هذه الميزة تتطلب بيانات رسمية/تاريخية وشراكات موثوقة. حالياً نعرض حالة الدخول فقط (بدون فيزا / e-visa / عند الوصول / تتطلب تأشيرة).
              </p>
            </div>
          </div>

          {/* Right: Highlights / CTA */}
          <div className="space-y-6">
            <div className="bg-white rounded-2xl shadow-sm border p-6">
              <div className="w-16 h-16 bg-blue-100 rounded-2xl flex items-center justify-center mb-4">
                <span className="text-2xl">✈️</span>
              </div>
              <h3 className="text-lg font-semibold mb-2">لماذا TravelInsight؟</h3>
              <ul className="text-sm text-gray-700 space-y-2 leading-6">
                <li>• واجهة واحدة تجمع أهم ما يحتاجه المسافر.</li>
                <li>• جاهز للربط مع مزودي بيانات موثوقين.</li>
                <li>• تصميم معياري قابل للتوسّع سريعًا.</li>
              </ul>
            </div>

            <div className="rounded-2xl p-6 bg-gradient-to-tr from-emerald-500 to-emerald-600 text-white">
              <h3 className="text-lg font-semibold mb-2">هل ترغب بمعاينة مباشرة للمستثمرين/العملاء؟</h3>
              <p className="text-emerald-50 text-sm mb-4">يمكن نشر النسخة الحالية على Vercel/Netlify خلال دقائق.</p>
              <div className="flex gap-3">
                <a href="/about" className="px-4 py-2 rounded-xl bg-white text-emerald-700 font-semibold hover:bg-emerald-50">تعرّف أكثر</a>
                <a href="/" className="px-4 py-2 rounded-xl border border-white/40 hover:bg-white/10">بدء التجربة</a>
              </div>
            </div>
          </div>
        </motion.section>

        {/* HOW IT WORKS */}
        <motion.section {...fadeUp(0.05)} className="mt-10 bg-white rounded-3xl shadow-sm border p-6 md:p-8">
          <h2 className="text-2xl md:text-3xl font-bold mb-4">كيف يعمل؟</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="p-5 rounded-2xl border">
              <div className="text-2xl mb-2">1️⃣</div>
              <h4 className="font-semibold mb-1">اختر الدول</h4>
              <p className="text-sm text-gray-600">حدّد دولة الانطلاق والوجهة لنظهر لك الحالة والتكلفة.</p>
            </div>
            <div className="p-5 rounded-2xl border">
              <div className="text-2xl mb-2">2️⃣</div>
              <h4 className="font-semibold mb-1">اطّلع على النتائج</h4>
              <p className="text-sm text-gray-600">حالة التأشيرة، تقدير الرحلة، ولمحة عن سوق العمل.</p>
            </div>
            <div className="p-5 rounded-2xl border">
              <div className="text-2xl mb-2">3️⃣</div>
              <h4 className="font-semibold mb-1">طوّر الخطة</h4>
              <p className="text-sm text-gray-600">أضف مصادر بيانات رسمية لاحقًا وخصّص التجربة.</p>
            </div>
          </div>
        </motion.section>

        {/* FOOTER */}
        <footer className="mt-10 text-center text-xs text-gray-500">
          © TravelInsight — نموذج منتج ببيانات تجريبية. للاستخدام التوضيحي فقط.
        </footer>
      </div>
    </div>
  );
}
