import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { api } from '../services/api';

const CostEstimator = () => {
  const [from, setFrom] = useState('PS');
  const [to, setTo] = useState('DE');
  const [days, setDays] = useState(6);
  const [countries, setCountries] = useState([]);
  const [costData, setCostData] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const loadCountries = async () => {
      try {
        const countriesData = await api.getCountries();
        setCountries(countriesData);
      } catch (error) {
        console.error('Error loading countries:', error);
      }
    };

    loadCountries();
  }, []);

  useEffect(() => {
    const loadCostData = async () => {
      if (from && to) {
        setLoading(true);
        try {
          const cost = await api.calculateTripCost(from, to, days);
          setCostData(cost);
        } catch (error) {
          console.error('Error loading cost data:', error);
        } finally {
          setLoading(false);
        }
      }
    };

    loadCostData();
  }, [from, to, days]);

  const handleDaysChange = (newDays) => {
    const validDays = Math.max(1, Math.min(30, parseInt(newDays) || 1));
    setDays(validDays);
  };

  const getCostBreakdown = () => {
    if (!costData) return [];
    
    return [
      { label: 'تكلفة الطيران', amount: costData.baseFlight, percentage: Math.round((costData.baseFlight / costData.total) * 100) },
      { label: 'المصاريف اليومية', amount: costData.daily * days, percentage: Math.round(((costData.daily * days) / costData.total) * 100) },
    ];
  };

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center mb-8"
        >
          <h1 className="text-3xl font-bold text-gray-900 mb-4">
            حاسبة التكلفة
          </h1>
          <p className="text-lg text-gray-600">
            احسب تكلفة رحلتك بدقة مع تفاصيل شاملة
          </p>
        </motion.div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Input Section */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.2 }}
            className="lg:col-span-1"
          >
            <div className="bg-white rounded-lg shadow-sm p-6 sticky top-8">
              <h2 className="text-xl font-semibold mb-6">إعدادات الرحلة</h2>
              
              <div className="space-y-6">
                {/* Country Selection */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    الدولة الحالية
                  </label>
                  <select
                    value={from}
                    onChange={(e) => setFrom(e.target.value)}
                    className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    disabled={loading}
                  >
                    {countries.map(country => (
                      <option key={country.code} value={country.code}>
                        {country.name}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    الدولة الوجهة
                  </label>
                  <select
                    value={to}
                    onChange={(e) => setTo(e.target.value)}
                    className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    disabled={loading}
                  >
                    {countries.map(country => (
                      <option key={country.code} value={country.code}>
                        {country.name}
                      </option>
                    ))}
                  </select>
                </div>

                {/* Days Selection */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    عدد الأيام
                  </label>
                  <div className="flex items-center space-x-2 rtl:space-x-reverse">
                    <button
                      onClick={() => handleDaysChange(days - 1)}
                      className="w-10 h-10 rounded-lg border border-gray-300 flex items-center justify-center hover:bg-gray-50"
                      disabled={days <= 1}
                    >
                      -
                    </button>
                    <input
                      type="number"
                      value={days}
                      onChange={(e) => handleDaysChange(e.target.value)}
                      min="1"
                      max="30"
                      className="flex-1 p-3 border border-gray-300 rounded-lg text-center focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    />
                    <button
                      onClick={() => handleDaysChange(days + 1)}
                      className="w-10 h-10 rounded-lg border border-gray-300 flex items-center justify-center hover:bg-gray-50"
                      disabled={days >= 30}
                    >
                      +
                    </button>
                  </div>
                </div>

                {/* Additional Options */}
                <div className="space-y-4">
                  <h3 className="font-medium text-gray-700">خيارات إضافية</h3>
                  
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">فندق 4 نجوم</span>
                    <span className="text-sm font-medium">+$50/ليلة</span>
                  </div>
                  
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">تأمين سفر</span>
                    <span className="text-sm font-medium">+$30</span>
                  </div>
                  
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">تأجير سيارة</span>
                    <span className="text-sm font-medium">+$40/يوم</span>
                  </div>
                </div>
              </div>
            </div>
          </motion.div>

          {/* Results Section */}
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.4 }}
            className="lg:col-span-2 space-y-6"
          >
            {/* Loading State */}
            {loading ? (
              <div className="bg-white rounded-lg shadow-sm p-8 text-center">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                <p className="mt-4 text-gray-600">جاري حساب التكلفة...</p>
              </div>
            ) : costData ? (
              <>
                {/* Total Cost Card */}
                <div className="bg-gradient-to-r from-blue-600 to-blue-700 rounded-lg shadow-lg p-8 text-white">
                  <h2 className="text-2xl font-bold mb-4">التكلفة الإجمالية</h2>
                  <div className="text-4xl font-bold mb-2">${costData.total.toLocaleString()}</div>
                  <p className="text-blue-100">
                    لرحلة {days} أيام من {countries.find(c => c.code === from)?.name} إلى {countries.find(c => c.code === to)?.name}
                  </p>
                </div>

                {/* Cost Breakdown */}
                <div className="bg-white rounded-lg shadow-sm p-6">
                  <h3 className="text-xl font-semibold mb-6">تفصيل التكلفة</h3>
                  
                  <div className="space-y-4">
                    {getCostBreakdown().map((item, index) => (
                      <div key={index} className="flex items-center justify-between py-3 border-b border-gray-100">
                        <div className="flex items-center space-x-3 rtl:space-x-reverse">
                          <div className="w-4 h-4 rounded-full bg-blue-100"></div>
                          <span className="font-medium">{item.label}</span>
                          <span className="text-sm text-gray-500">({item.percentage}%)</span>
                        </div>
                        <span className="font-semibold">${item.amount.toLocaleString()}</span>
                      </div>
                    ))}
                  </div>

                  <div className="mt-6 pt-4 border-t border-gray-200">
                    <div className="flex items-center justify-between">
                      <span className="text-lg font-semibold">الإجمالي</span>
                      <span className="text-2xl font-bold text-blue-600">${costData.total.toLocaleString()}</span>
                    </div>
                  </div>
                </div>

                {/* Cost Analysis */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {/* Daily Average */}
                  <div className="bg-white rounded-lg shadow-sm p-6">
                    <h4 className="font-semibold mb-4">متوسط التكلفة اليومية</h4>
                    <div className="text-3xl font-bold text-green-600 mb-2">
                      ${Math.round(costData.total / days)}
                    </div>
                    <p className="text-sm text-gray-600">
                      لكل يوم من أيام الرحلة
                    </p>
                  </div>

                  {/* Flight vs Accommodation */}
                  <div className="bg-white rounded-lg shadow-sm p-6">
                    <h4 className="font-semibold mb-4">توزيع التكلفة</h4>
                    <div className="space-y-3">
                      <div className="flex items-center justify-between">
                        <span className="text-sm text-gray-600">الطيران</span>
                        <span className="font-medium">
                          {Math.round((costData.baseFlight / costData.total) * 100)}%
                        </span>
                      </div>
                      <div className="flex items-center justify-between">
                        <span className="text-sm text-gray-600">المصاريف اليومية</span>
                        <span className="font-medium">
                          {Math.round(((costData.daily * days) / costData.total) * 100)}%
                        </span>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Tips and Recommendations */}
                <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-6">
                  <h4 className="font-semibold text-yellow-800 mb-4">نصائح لتوفير المال</h4>
                  <ul className="space-y-2 text-sm text-yellow-700">
                    <li>• احجز الطيران مبكراً لتوفير 20-30% من التكلفة</li>
                    <li>• اختر الإقامة في المناطق الوسطى لتوفير تكلفة المواصلات</li>
                    <li>• استخدم وسائل النقل العام بدلاً من التاكسي</li>
                    <li>• ابحث عن العروض والخصومات المتاحة</li>
                  </ul>
                </div>

                {/* Disclaimer */}
                <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
                  <p className="text-xs text-gray-600 text-center">
                    * هذه التقديرات تجريبية/مقترحة لأغراض العرض التوضيحي. 
                    الأسعار الفعلية قد تختلف حسب الموسم والطلب والظروف الاقتصادية.
                  </p>
                </div>
              </>
            ) : null}
          </motion.div>
        </div>
      </div>
    </div>
  );
};

export default CostEstimator;
