import React from 'react';
import { motion } from 'framer-motion';

const fadeUp = (delay = 0) => ({
  initial: { opacity: 0, y: 18 },
  animate: { opacity: 1, y: 0, transition: { duration: 0.5, delay } }
});

const Badge = ({ children }) => (
  <span className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/70 border border-white/60 text-sm shadow-sm">
    {children}
  </span>
);

const Stat = ({ icon, label, value, delay }) => (
  <motion.div {...fadeUp(delay)} className="p-5 rounded-2xl bg-white shadow-sm border">
    <div className="text-2xl mb-2">{icon}</div>
    <div className="text-3xl font-extrabold">{value}</div>
    <div className="text-gray-500 text-sm">{label}</div>
  </motion.div>
);

const FeatureCard = ({ icon, title, description, delay }) => (
  <motion.div {...fadeUp(delay)} className="bg-white rounded-2xl shadow-sm border p-6 hover:shadow-md transition-shadow">
    <div className="text-4xl mb-4">{icon}</div>
    <h3 className="text-xl font-semibold mb-2">{title}</h3>
    <p className="text-gray-600">{description}</p>
  </motion.div>
);

const RoadmapItem = ({ step, title, text, delay }) => (
  <motion.div {...fadeUp(delay)} className="relative pl-8">
    <div className="absolute left-0 top-1 w-6 h-6 rounded-full bg-blue-600 text-white text-sm flex items-center justify-center font-bold">{step}</div>
    <h4 className="font-semibold mb-1">{title}</h4>
    <p className="text-gray-600 text-sm leading-6">{text}</p>
  </motion.div>
);

const FAQItem = ({ q, a, delay }) => (
  <motion.details {...fadeUp(delay)} className="group bg-white rounded-xl border p-4">
    <summary className="cursor-pointer font-medium flex items-center justify-between">
      <span>{q}</span>
      <span className="text-gray-400 group-open:rotate-180 transition-transform">⌄</span>
    </summary>
    <div className="pt-3 text-gray-600">{a}</div>
  </motion.details>
);

const About = () => {
  const features = [
    { icon: '🛂', title: 'معلومات التأشيرات', description: 'قواعد الدخول حسب الجنسية (بدون فيزا / e-visa / عند الوصول / تتطلب تأشيرة).' },
    { icon: '💰', title: 'حاسبة التكلفة', description: 'تقدير تذاكر الطيران والمصاريف اليومية وملخص إجمالي للرحلة.' },
    { icon: '💼', title: 'سوق العمل', description: 'لقطات رواتب وفرص عمل شائعة لكل وجهة (بيانات تجريبية قابلة للاستبدال بـ APIs).' },
    { icon: '🗺️', title: 'الخطط السياحية', description: 'اقتراح مسارات وأنشطة قابلة للتعديل حسب اهتمامات المسافر.' },
  ];

  return (
    <div dir="rtl" className="min-h-screen bg-gradient-to-b from-blue-50 via-slate-50 to-white">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-10">

        {/* Hero */}
        <motion.section {...fadeUp(0)} className="relative overflow-hidden rounded-3xl bg-gradient-to-tr from-blue-600 to-indigo-600 text-white p-8 md:p-12 mb-10">
          <div className="relative z-10">
            <div className="flex flex-wrap items-center gap-3 mb-5">
              <Badge>🚧 نموذج منتج (Concept App)</Badge>
              <Badge>✨ نسخة أولية للتجربة</Badge>
            </div>
            <h1 className="text-3xl md:text-5xl font-extrabold leading-tight">
              TravelInsight — التخطيط الذكي للسفر، في صفحة واحدة
            </h1>
            <p className="mt-4 md:text-lg text-blue-100/90 max-w-3xl">
              هذا تطبيق لفكرة منتج: يجمع رؤوس أقلام أساسية للمسافر — حالة التأشيرات، تقدير التكاليف، لمحة عن سوق العمل، ومسارات سياحية — في تجربة بسيطة قابلة للتوسّع.
            </p>
            <div className="mt-6 flex flex-wrap gap-3">
              <a href="/" className="px-5 py-3 rounded-xl bg-white text-blue-700 font-semibold hover:bg-blue-50 shadow">
                جرّب النسخة التفاعلية
              </a>
              <a href="#" className="px-5 py-3 rounded-xl bg-blue-500/30 border border-white/30 hover:bg-blue-500/40">
                اطّلع على الخطة التقنية
              </a>
            </div>
          </div>
          <div className="absolute -left-24 -bottom-24 w-72 h-72 bg-white/10 rounded-full blur-2xl" />
          <div className="absolute -right-20 -top-20 w-64 h-64 bg-white/10 rounded-full blur-2xl" />
        </motion.section>

        {/* Quick stats */}
        <section className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-10">
          <Stat icon="⚡" label="واجهة جاهزة للتكامل مع APIs" value="Modular" delay={0.05} />
          <Stat icon="🧩" label="مكوّنات منفصلة قابلة لإعادة الاستخدام" value="Composable" delay={0.1} />
          <Stat icon="🚀" label="مناسبة للعرض للمستثمرين والعملاء" value="Demo-Ready" delay={0.15} />
        </section>

        {/* What is this */}
        <motion.section {...fadeUp(0.05)} className="bg-white rounded-3xl shadow-sm border p-6 md:p-8 mb-10">
          <h2 className="text-2xl md:text-3xl font-bold mb-3">ما هو TravelInsight؟</h2>
          <p className="text-gray-700 leading-8">
            TravelInsight هو <span className="font-semibold">نموذج أولي لفكرة منتج</span> يستعرض كيف يمكن
            دمج بيانات السفر الأساسية في واجهة واحدة. الغرض توضيح الرؤية، وليس تقديم بيانات نهائية. يمكن استبدال
            البيانات التجريبية بمصادر موثوقة مثل مزوّدي التأشيرات وتكاليف المعيشة ومنصات الوظائف.
          </p>
          <div className="mt-5 grid grid-cols-1 lg:grid-cols-4 gap-6">
            {features.map((f, i) => (
              <FeatureCard key={i} icon={f.icon} title={f.title} description={f.description} delay={0.1 + i * 0.05} />
            ))}
          </div>
        </motion.section>

        {/* Concept vs Product */}
        <motion.section {...fadeUp(0.05)} className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-10">
          <div className="rounded-2xl border bg-white p-6">
            <h3 className="text-xl font-bold mb-2">كنموذج فكرة (اليوم)</h3>
            <ul className="space-y-2 text-gray-700 list-disc pr-5">
              <li>بيانات تجريبية (mocks) موحّدة في ملف واحد.</li>
              <li>مكوّنات UI منفصلة (Visa, Cost, Jobs, Itinerary).</li>
              <li>تبديل اللغة ممكن (i18n) عند تفعيل ملفات الترجمة.</li>
            </ul>
          </div>
          <div className="rounded-2xl border bg-white p-6">
            <h3 className="text-xl font-bold mb-2">كمنتج فعلي (الخطوة التالية)</h3>
            <ul className="space-y-2 text-gray-700 list-disc pr-5">
              <li>ربط مزوّدي التأشيرات المعتمدين (Timatic/Sherpa)، وتكاليف السفر (Flights/Transport)، والوظائف/الرواتب.</li>
              <li>لوحة تفضيلات المستخدم + حفظ خطط السفر.</li>
              <li>تحليلات استخدام + تصنيف الوجهات وتخصيص التوصيات.</li>
            </ul>
          </div>
        </motion.section>

        {/* Roadmap */}
        <motion.section {...fadeUp(0.05)} className="bg-white rounded-3xl shadow-sm border p-6 md:p-8 mb-10">
          <h2 className="text-2xl md:text-3xl font-bold mb-4">خريطة الطريق</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <RoadmapItem step="1" title="MVP ببيانات تجريبية" text="صفحات منفصلة + Router + فصل البيانات عن الواجهة عبر طبقة خدمات." delay={0.05} />
            <RoadmapItem step="2" title="تكامل APIs" text="مصادر رسمية للتأشيرات وتكاليف المعيشة والوظائف مع كاش وتحديث دوري." delay={0.1} />
            <RoadmapItem step="3" title="تخصيص وتجربة مستخدم" text="ملف مستخدم، تفضيلات، إشعارات، وحفظ خطط السفر." delay={0.15} />
            <RoadmapItem step="4" title="الإطلاق والتوسع" text="مؤشرات الأداء، دعم لغات إضافية، وتوسعة مصادر البيانات." delay={0.2} />
          </div>
        </motion.section>

        {/* FAQ */}
        <motion.section {...fadeUp(0.05)} className="grid grid-cols-1 lg:grid-cols-2 gap-4 mb-10">
          <FAQItem
            q="هل البيانات في التطبيق نهائية ودقيقة؟"
            a="لا، هذه نسخة نموذجية للعرض فقط. الهدف توضيح الفكرة وتجربة الواجهة. عند التحويل لمنتج سيتم ربط مصادر رسمية والالتزام بالتحديثات."
            delay={0.05}
          />
          <FAQItem
            q="هل يمكن ربطه بمصادر بيانات حقيقية؟"
            a="نعم، البنية مُحضّرة لطبقة خدمات (Service Layer) لاستبدال الـ mocks بواجهات APIs مثل التأشيرات، الرحلات، وتكاليف المعيشة."
            delay={0.08}
          />
          <FAQItem
            q="هل يدعم لغات متعددة؟"
            a="يمكن تفعيل i18n (react-i18next) بسرعة وإضافة ملفات ترجمة لكل صفحة ومكوّن."
            delay={0.11}
          />
          <FAQItem
            q="كيف يمكنني تجربة الفكرة؟"
            a="استخدم الروابط في الأعلى لتجربة النسخة التفاعلية، أو انشرها على Vercel/Netlify مباشرة."
            delay={0.14}
          />
        </motion.section>

        {/* Call to action + Disclaimer */}
        <motion.section {...fadeUp(0.05)} className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between bg-white rounded-2xl border p-6">
          <div>
            <h3 className="text-xl font-bold mb-1">مهتم تبني الفكرة أو التعاون؟</h3>
            <p className="text-gray-600">تواصل معي لعرض الخطة التقنية والتكامل مع مزوّدي البيانات.</p>
          </div>
          <div className="flex gap-3">
            <a href="/" className="px-5 py-3 rounded-xl bg-blue-600 text-white font-semibold hover:bg-blue-700">جرب النسخة</a>
            <a href="#" className="px-5 py-3 rounded-xl border hover:bg-gray-50">عرض الوثيقة التقنية</a>
          </div>
        </motion.section>

        <motion.p {...fadeUp(0.05)} className="mt-6 text-center text-sm text-yellow-700 bg-yellow-50 border border-yellow-200 p-4 rounded-xl">
          تنبيه: هذا تطبيق لفكرة (Concept) ببيانات تجريبية للتوضيح فقط — ليست معلومات رسمية. يُنصح بالرجوع للمصادر الحكومية/الرسمية قبل اتخاذ قرارات السفر.
        </motion.p>
      </div>
    </div>
  );
};

export default About;
