import React from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';

const NotFound = () => {
  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center">
      <div className="max-w-md mx-auto text-center px-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white rounded-lg shadow-sm p-8"
        >
          {/* 404 Icon */}
          <div className="text-6xl mb-6">🔍</div>
          
          {/* Error Message */}
          <h1 className="text-4xl font-bold text-gray-900 mb-4">
            404
          </h1>
          
          <h2 className="text-2xl font-semibold text-gray-700 mb-4">
            الصفحة غير موجودة
          </h2>
          
          <p className="text-gray-600 mb-8">
            عذراً، الصفحة التي تبحث عنها غير موجودة أو تم نقلها إلى مكان آخر.
          </p>
          
          {/* Action Buttons */}
          <div className="space-y-4">
            <Link
              to="/"
              className="block w-full px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium"
            >
              العودة إلى الصفحة الرئيسية
            </Link>
            
            <button
              onClick={() => window.history.back()}
              className="block w-full px-6 py-3 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors font-medium"
            >
              العودة للصفحة السابقة
            </button>
          </div>
          
          {/* Help Text */}
          <div className="mt-8 text-sm text-gray-500">
            <p>إذا كنت تعتقد أن هذا خطأ، يرجى</p>
            <Link to="/about" className="text-blue-600 hover:text-blue-700 underline">
              التواصل معنا
            </Link>
          </div>
        </motion.div>
      </div>
    </div>
  );
};

export default NotFound;
