import React, { useEffect, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';

export default function Navbar() {
  const [isArabic, setIsArabic] = useState(true);
  const [open, setOpen] = useState(false);
  const location = useLocation();

  // قفل التمرير أثناء فتح قائمة الموبايل
  useEffect(() => {
    document.body.style.overflow = open ? 'hidden' : '';
    return () => (document.body.style.overflow = '');
  }, [open]);

  const navItems = [
    { path: '/', labelAr: 'الرئيسية', labelEn: 'Home' },
    {
      path: '/visa-lookup',
      labelAr: 'البحث عن التأشيرة',
      labelEn: 'Visa Lookup',
    },
    {
      path: '/cost-estimator',
      labelAr: 'حاسبة التكلفة',
      labelEn: 'Cost Estimator',
    },
    { path: '/jobs-snapshot', labelAr: 'سوق العمل', labelEn: 'Jobs Snapshot' },
    { path: '/itinerary', labelAr: 'الخطة السياحية', labelEn: 'Itinerary' },
    { path: '/about', labelAr: 'حول التطبيق', labelEn: 'About' },
  ];

  const t = (ar, en) => (isArabic ? ar : en);

  return (
    <header className="sticky top-0 z-50 bg-white/90 backdrop-blur border-b">
      <nav className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
        {/* Logo */}
        <Link
          to="/"
          className="flex items-center gap-2"
          onClick={() => setOpen(false)}
        >
          <div className="w-8 h-8 bg-blue-600 rounded-lg grid place-items-center">
            <span className="text-white font-bold text-sm">T</span>
          </div>
          <span className="text-xl font-bold text-gray-900">TravelInsight</span>
        </Link>

        {/* Desktop links */}
        <div className="hidden md:flex items-center gap-6">
          {navItems.map(item => {
            const active = location.pathname === item.path;
            return (
              <Link
                key={item.path}
                to={item.path}
                className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  active
                    ? 'text-blue-600 bg-blue-50'
                    : 'text-gray-700 hover:text-blue-600 hover:bg-gray-50'
                }`}
              >
                {t(item.labelAr, item.labelEn)}
              </Link>
            );
          })}

          {/* Lang toggle */}
          <button
            onClick={() => setIsArabic(!isArabic)}
            className="px-3 py-1 text-sm bg-gray-100 hover:bg-gray-200 rounded-md transition-colors"
          >
            {isArabic ? 'EN' : 'عربي'}
          </button>

          <Link
            to="/"
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-sm font-medium"
          >
            {t('جرب التطبيق', 'Try Demo')}
          </Link>
        </div>

        {/* Mobile actions */}
        <div className="md:hidden flex items-center gap-2">
          {/* Lang toggle (mobile) */}
          <button
            onClick={() => setIsArabic(!isArabic)}
            className="px-3 py-1 text-sm bg-gray-100 hover:bg-gray-200 rounded-md transition-colors"
            aria-label="Toggle language"
          >
            {isArabic ? 'EN' : 'عربي'}
          </button>

          {/* Hamburger */}
          <button
            onClick={() => setOpen(v => !v)}
            className="p-2 rounded-md border hover:bg-gray-50"
            aria-label="Open menu"
            aria-expanded={open}
          >
            <span className="block w-5 h-0.5 bg-gray-800 mb-1"></span>
            <span className="block w-5 h-0.5 bg-gray-800 mb-1"></span>
            <span className="block w-5 h-0.5 bg-gray-800"></span>
          </button>
        </div>
      </nav>

      {/* Mobile menu panel */}
      {open && (
        <>
          {/* خلفية معتمة */}
          <div
            className="fixed inset-0 bg-black/30 md:hidden"
            onClick={() => setOpen(false)}
          />
          {/* القائمة */}
          <div className="fixed top-16 inset-x-0 md:hidden bg-white border-b shadow-lg">
            <div className="px-4 py-4 flex flex-col gap-1">
              {navItems.map(item => {
                const active = location.pathname === item.path;
                return (
                  <Link
                    key={item.path}
                    to={item.path}
                    onClick={() => setOpen(false)}
                    className={`px-3 py-3 rounded-md text-base font-medium transition-colors ${
                      active
                        ? 'text-blue-600 bg-blue-50'
                        : 'text-gray-800 hover:text-blue-600 hover:bg-gray-50'
                    }`}
                  >
                    {t(item.labelAr, item.labelEn)}
                  </Link>
                );
              })}

              <Link
                to="/"
                onClick={() => setOpen(false)}
                className="mt-2 px-4 py-2 text-center bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-sm font-medium"
              >
                {t('جرب التطبيق', 'Try Demo')}
              </Link>
            </div>
          </div>
        </>
      )}
    </header>
  );
}
